fn less_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // If you want to ensure at runtime that the lengths match, you can uncomment the next line:
    // assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    
    // Zip the two vectors together and compare element-wise.
    a.iter()
     .zip(b.iter())
     .map(|(x, y)| x <= y)
     .collect()
}

